  1 | /*
  2 |  * Legacy reporting module (2019). Builds the nightly usage report that ops emails out.
  3 |  * Written before the ESM migration; still used by scripts/nightly (not in this repo).
  4 |  * Please do not change the output format without telling ops.
  5 |  */
  6 | 
  7 | import { normalizeWhitespace, truncate } from '../utils/strings.js';
  8 | 
  9 | var DAY_MS = 24 * 60 * 60 * 1000;
 10 | var DEFAULT_LOCALE = 'en-US';
 11 | var MAX_TOP = 10;
 12 | 
 13 | function pad2(n) {
 14 |   var s = String(n);
 15 |   if (s.length < 2) {
 16 |     s = "0" + s;
 17 |   }
 18 |   return s;
 19 | }
 20 | 
 21 | function formatDate(d) {
 22 |   var date = new Date(d);
 23 |   if (isNaN(date.getTime())) {
 24 |     return "unknown";
 25 |   }
 26 |   return date.getFullYear() + "-" + pad2(date.getMonth() + 1) + "-" + pad2(date.getDate());
 27 | }
 28 | 
 29 | function formatNumber(n) {
 30 |   if (n === null || n === undefined) {
 31 |     return "-";
 32 |   }
 33 |   var parts = String(Math.round(n)).split("");
 34 |   var result = "";
 35 |   var count = 0;
 36 |   for (var i = parts.length - 1; i >= 0; i--) {
 37 |     result = parts[i] + result;
 38 |     count++;
 39 |     if (count % 3 === 0 && i > 0) {
 40 |       result = "," + result;
 41 |     }
 42 |   }
 43 |   return result;
 44 | }
 45 | 
 46 | function percent(part, total) {
 47 |   if (!total) {
 48 |     return "0%";
 49 |   }
 50 |   var p = (part / total) * 100;
 51 |   return (Math.round(p * 10) / 10) + "%";
 52 | }
 53 | 
 54 | function withinDays(notes, days, now) {
 55 |   var cutoff = (now || Date.now()) - days * DAY_MS;
 56 |   var result = [];
 57 |   for (var i = 0; i < notes.length; i++) {
 58 |     var t = new Date(notes[i].createdAt).getTime();
 59 |     if (t >= cutoff) {
 60 |       result.push(notes[i]);
 61 |     }
 62 |   }
 63 |   return result;
 64 | }
 65 | 
 66 | function countByTag(notes) {
 67 |   var counts = {};
 68 |   for (var i = 0; i < notes.length; i++) {
 69 |     var tags = notes[i].tags || [];
 70 |     for (var j = 0; j < tags.length; j++) {
 71 |       var tag = tags[j];
 72 |       if (!counts[tag]) {
 73 |         counts[tag] = 0;
 74 |       }
 75 |       counts[tag] = counts[tag] + 1;
 76 |     }
 77 |   }
 78 |   return counts;
 79 | }
 80 | 
 81 | function topEntries(counts, limit) {
 82 |   var entries = [];
 83 |   for (var key in counts) {
 84 |     if (Object.prototype.hasOwnProperty.call(counts, key)) {
 85 |       entries.push({ key: key, value: counts[key] });
 86 |     }
 87 |   }
 88 |   entries.sort(function (a, b) {
 89 |     if (b.value !== a.value) {
 90 |       return b.value - a.value;
 91 |     }
 92 |     return a.key < b.key ? -1 : 1;
 93 |   });
 94 |   return entries.slice(0, limit || MAX_TOP);
 95 | }
 96 | 
 97 | function countByAuthor(notes) {
 98 |   var counts = {};
 99 |   for (var i = 0; i < notes.length; i++) {
100 |     var author = notes[i].author || "unknown";
101 |     counts[author] = (counts[author] || 0) + 1;
102 |   }
103 |   return counts;
104 | }
105 | 
106 | function averageLength(notes) {
107 |   if (!notes.length) {
108 |     return 0;
109 |   }
110 |   var total = 0;
111 |   for (var i = 0; i < notes.length; i++) {
112 |     total += (notes[i].body || "").length;
113 |   }
114 |   return total / notes.length;
115 | }
116 | 
117 | function longestNote(notes) {
118 |   var best = null;
119 |   for (var i = 0; i < notes.length; i++) {
120 |     if (!best || (notes[i].body || "").length > (best.body || "").length) {
121 |       best = notes[i];
122 |     }
123 |   }
124 |   return best;
125 | }
