127 | function buildDailySection(notes, now) {
128 |   var recent = withinDays(notes, 1, now);
129 |   var tags = topEntries(countByTag(recent), 5);
130 |   var authors = topEntries(countByAuthor(recent), 5);
131 |   var lines = [];
132 |   lines.push("== Daily (last 1 day) ==");
133 |   lines.push("Notes created: " + formatNumber(recent.length));
134 |   lines.push("Share of all notes: " + percent(recent.length, notes.length));
135 |   lines.push("Average length: " + formatNumber(averageLength(recent)) + " chars");
136 |   if (tags.length) {
137 |     lines.push("Top tags:");
138 |     for (var i = 0; i < tags.length; i++) {
139 |       lines.push("  " + (i + 1) + ". " + tags[i].key + " (" + tags[i].value + ")");
140 |     }
141 |   } else {
142 |     lines.push("Top tags: none");
143 |   }
144 |   if (authors.length) {
145 |     lines.push("Most active:");
146 |     for (var j = 0; j < authors.length; j++) {
147 |       lines.push("  " + authors[j].key + ": " + authors[j].value);
148 |     }
149 |   }
150 |   var longest = longestNote(recent);
151 |   if (longest) {
152 |     lines.push("Longest note: " + truncate(normalizeWhitespace(longest.title), 40) + " (" + formatDate(longest.createdAt) + ")");
153 |   }
154 |   return lines.join("\n");
155 | }
