247 | function buildHeader(title, now) {
248 |   var lines = [];
249 |   lines.push("=".repeat(60));
250 |   lines.push(title);
251 |   lines.push("Generated: " + formatDate(now || Date.now()));
252 |   lines.push("=".repeat(60));
253 |   return lines.join("\n");
