256 | function buildFooter(notes) {
257 |   var lines = [];
258 |   lines.push("-".repeat(60));
259 |   lines.push("Total notes: " + formatNumber(notes.length));
260 |   lines.push("Distinct tags: " + Object.keys(countByTag(notes)).length);
261 |   lines.push("Report format v3. Questions: #ops-reports");
