265 | function toCsvRow(values) {
266 |   var cells = [];
267 |   for (var i = 0; i < values.length; i++) {
268 |     var v = values[i] === undefined || values[i] === null ? "" : String(values[i]);
269 |     if (v.indexOf(",") !== -1 || v.indexOf("\"") !== -1) {
270 |       v = "\"" + v.replace(/"/g, "\"\"") + "\"";
271 |     }
272 |     cells.push(v);
273 |   }
274 |   return cells.join(",");
275 | }
