277 | function buildCsv(notes) {
278 |   var rows = [toCsvRow(["id", "title", "author", "tags", "created"])];
279 |   for (var i = 0; i < notes.length; i++) {
280 |     var n = notes[i];
281 |     rows.push(toCsvRow([n.id, n.title, n.author, (n.tags || []).join(" "), formatDate(n.createdAt)]));
282 |   }
283 |   return rows.join("\n");
284 | }
