286 | function validateOptions(options) {
287 |   var opts = options || {};
288 |   var result = { sections: ["daily", "weekly", "monthly"], format: "text", now: Date.now() };
289 |   if (opts.sections) {
290 |     if (!Array.isArray(opts.sections)) {
291 |       throw new Error("sections must be an array");
292 |     }
293 |     result.sections = opts.sections;
294 |   }
295 |   if (opts.format) {
296 |     if (opts.format !== "text" && opts.format !== "csv") {
297 |       throw new Error("unknown format: " + opts.format);
298 |     }
299 |     result.format = opts.format;
300 |   }
301 |   if (opts.now) {
302 |     result.now = opts.now;
303 |   }
304 |   return result;
305 | }
