307 | function buildReport(notes, options) {
308 |   var opts = validateOptions(options);
309 |   if (opts.format === "csv") {
310 |     return buildCsv(notes);
311 |   }
312 |   var parts = [buildHeader("Notes usage report", opts.now)];
313 |   for (var i = 0; i < opts.sections.length; i++) {
314 |     var s = opts.sections[i];
315 |     if (s === "daily") {
316 |       parts.push(buildDailySection(notes, opts.now));
317 |     } else if (s === "weekly") {
318 |       parts.push(buildWeeklySection(notes, opts.now));
319 |     } else if (s === "monthly") {
320 |       parts.push(buildMonthlySection(notes, opts.now));
321 |     } else if (s === "quarterly") {
322 |       parts.push(buildQuarterlySection(notes, opts.now));
323 |     } else {
324 |       parts.push("(unknown section: " + s + ")");
325 |     }
326 |   }
327 |   parts.push(buildFooter(notes));
328 |   return parts.join("\n\n");
329 | }
