331 | function escapeHtml(s) {
332 |   return String(s)
333 |     .replace(/&/g, "&amp;")
334 |     .replace(/</g, "&lt;")
335 |     .replace(/>/g, "&gt;")
336 |     .replace(/"/g, "&quot;");
337 | }
338 | 
339 | function weekdayName(d) {
340 |   var names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
341 |   return names[new Date(d).getDay()];
342 | }
343 | 
344 | function countByWeekday(notes) {
345 |   var counts = {};
346 |   for (var i = 0; i < notes.length; i++) {
347 |     var day = weekdayName(notes[i].createdAt);
348 |     counts[day] = (counts[day] || 0) + 1;
349 |   }
350 |   return counts;
351 | }
