353 | function buildWeekdaySection(notes) {
354 |   var counts = countByWeekday(notes);
355 |   var order = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
356 |   var lines = ["== By weekday =="];
357 |   var max = 0;
358 |   for (var k in counts) {
359 |     if (counts[k] > max) {
360 |       max = counts[k];
361 |     }
362 |   }
363 |   for (var i = 0; i < order.length; i++) {
364 |     var n = counts[order[i]] || 0;
365 |     var bar = max ? "#".repeat(Math.round((n / max) * 30)) : "";
366 |     lines.push((order[i] + "          ").slice(0, 10) + " " + bar + " " + n);
367 |   }
368 |   return lines.join("\n");
369 | }
