371 | function buildHtml(notes, options) {
372 |   var text = buildReport(notes, options);
373 |   var lines = text.split("\n");
374 |   var html = ["<!doctype html>", "<html>", "<head>", "<meta charset=\"utf-8\">", "<title>Notes usage report</title>", "</head>", "<body>", "<pre>"];
375 |   for (var i = 0; i < lines.length; i++) {
376 |     html.push(escapeHtml(lines[i]));
377 |   }
378 |   html.push("</pre>");
379 |   html.push("</body>");
380 |   html.push("</html>");
381 |   return html.join("\n");
382 | }
