384 | function summarize(notes) {
385 |   return {
386 |     total: notes.length,
387 |     tags: Object.keys(countByTag(notes)).length,
388 |     averageLength: Math.round(averageLength(notes)),
389 |     busiestDay: topEntries(countByWeekday(notes), 1).map(function (e) { return e.key; })[0] || null,
390 |   };
391 | }
392 | 
393 | function compareSummaries(before, after) {
394 |   var diff = {};
395 |   var keys = ["total", "tags", "averageLength"];
396 |   for (var i = 0; i < keys.length; i++) {
397 |     var k = keys[i];
398 |     diff[k] = (after[k] || 0) - (before[k] || 0);
399 |   }
400 |   diff.busiestDayChanged = before.busiestDay !== after.busiestDay;
401 |   return diff;
402 | }
403 | 
404 | function describeChange(diff) {
405 |   var parts = [];
406 |   if (diff.total) {
407 |     parts.push((diff.total > 0 ? "+" : "") + formatNumber(diff.total) + " notes");
408 |   }
409 |   if (diff.tags) {
410 |     parts.push((diff.tags > 0 ? "+" : "") + diff.tags + " tags");
411 |   }
412 |   if (diff.averageLength) {
413 |     parts.push("average length " + (diff.averageLength > 0 ? "up " : "down ") + Math.abs(diff.averageLength) + " chars");
414 |   }
415 |   if (diff.busiestDayChanged) {
416 |     parts.push("busiest day changed");
417 |   }
418 |   return parts.length ? parts.join(", ") : "no change";
419 | }
420 | 
421 | export { buildHtml, buildWeekdaySection, summarize, compareSummaries, describeChange, buildReport, buildCsv, formatDate, formatNumber, percent, countByTag, topEntries };

