/*
 * Legacy reporting module (2019). Builds the nightly usage report that ops emails out.
 * Written before the ESM migration; still used by scripts/nightly (not in this repo).
 * Please do not change the output format without telling ops.
 */

import { normalizeWhitespace, truncate } from '../utils/strings.js';

const DAY_MS = 24 * 60 * 60 * 1000;
const MAX_TOP = 10;
const RULE = '-'.repeat(60);
const BAR = '='.repeat(60);
const SECTIONS = {
  daily: ['Daily (last 1 day)', 1],
  weekly: ['Weekly (last 7 days)', 7],
  monthly: ['Monthly (last 30 days)', 30],
  quarterly: ['Quarterly (last 91 days)', 91],
};
const WEEK = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

const pad2 = (n) => String(n).padStart(2, '0');
const bodyLength = (note) => (note.body || '').length;
const sign = (n) => (n > 0 ? '+' : '');

function formatDate(d) {
  const date = new Date(d);
  if (isNaN(date)) return 'unknown';
  return `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;
}

const formatNumber = (n) =>
  n == null ? '-' : String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

function percent(part, total) {
  return total ? `${Math.round((part / total) * 1000) / 10}%` : '0%';
}

function tally(items) {
  const counts = Object.create(null);
  for (const item of items) counts[item] = (counts[item] || 0) + 1;
  return counts;
}

const countByTag = (notes) => tally(notes.flatMap((n) => n.tags || []));
const countByAuthor = (notes) => tally(notes.map((n) => n.author || 'unknown'));
const weekdayName = (d) => WEEK[(new Date(d).getDay() + 6) % 7];
const countByWeekday = (notes) => tally(notes.map((n) => weekdayName(n.createdAt)));

function topEntries(counts, limit) {
  return Object.entries(counts)
    .map(([key, value]) => ({ key, value }))
    .sort((a, b) => b.value - a.value || (a.key < b.key ? -1 : 1))
    .slice(0, limit || MAX_TOP);
}

function withinDays(notes, days, now) {
  const cutoff = (now || Date.now()) - days * DAY_MS;
  return notes.filter((n) => new Date(n.createdAt).getTime() >= cutoff);
}

const averageLength = (notes) =>
  notes.length ? notes.reduce((sum, n) => sum + bodyLength(n), 0) / notes.length : 0;

const longestNote = (notes) =>
  notes.reduce((best, n) => (!best || bodyLength(n) > bodyLength(best) ? n : best), null);

function buildSection(name, notes, now) {
  const [label, days] = SECTIONS[name];
  const recent = withinDays(notes, days, now);
  const tags = topEntries(countByTag(recent), 5);
  const authors = topEntries(countByAuthor(recent), 5);
  const longest = longestNote(recent);
  return [
    `== ${label} ==`,
    `Notes created: ${formatNumber(recent.length)}`,
    `Share of all notes: ${percent(recent.length, notes.length)}`,
    `Average length: ${formatNumber(averageLength(recent))} chars`,
    ...(tags.length
      ? ['Top tags:', ...tags.map((t, i) => `  ${i + 1}. ${t.key} (${t.value})`)]
      : ['Top tags: none']),
    ...(authors.length ? ['Most active:', ...authors.map((a) => `  ${a.key}: ${a.value}`)] : []),
    ...(longest
      ? [`Longest note: ${truncate(normalizeWhitespace(longest.title), 40)} (${formatDate(longest.createdAt)})`]
      : []),
  ].join('\n');
}

const buildHeader = (title, now) =>
  [BAR, title, `Generated: ${formatDate(now || Date.now())}`, BAR].join('\n');

const buildFooter = (notes) =>
  [
    RULE,
    `Total notes: ${formatNumber(notes.length)}`,
    `Distinct tags: ${Object.keys(countByTag(notes)).length}`,
    'Report format v3. Questions: #ops-reports',
  ].join('\n');

function toCsvRow(values) {
  return values
    .map((v) => {
      const s = v == null ? '' : String(v);
      return /[,"]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
    })
    .join(',');
}

const buildCsv = (notes) =>
  [
    toCsvRow(['id', 'title', 'author', 'tags', 'created']),
    ...notes.map((n) =>
      toCsvRow([n.id, n.title, n.author, (n.tags || []).join(' '), formatDate(n.createdAt)])),
  ].join('\n');

function validateOptions({ sections, format, now } = {}) {
  if (sections && !Array.isArray(sections)) throw new Error('sections must be an array');
  if (format && format !== 'text' && format !== 'csv') throw new Error(`unknown format: ${format}`);
  return {
    sections: sections || ['daily', 'weekly', 'monthly'],
    format: format || 'text',
    now: now || Date.now(),
  };
}

function buildReport(notes, options) {
  const opts = validateOptions(options);
  if (opts.format === 'csv') return buildCsv(notes);
  return [
    buildHeader('Notes usage report', opts.now),
    ...opts.sections.map((s) =>
      s in SECTIONS ? buildSection(s, notes, opts.now) : `(unknown section: ${s})`),
    buildFooter(notes),
  ].join('\n\n');
}

function buildWeekdaySection(notes) {
  const counts = countByWeekday(notes);
  const max = Math.max(0, ...Object.values(counts));
  return [
    '== By weekday ==',
    ...WEEK.map((day) => {
      const n = counts[day] || 0;
      return `${day.padEnd(10)} ${max ? '#'.repeat(Math.round((n / max) * 30)) : ''} ${n}`;
    }),
  ].join('\n');
}

const escapeHtml = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const buildHtml = (notes, options) =>
  [
    '<!doctype html>', '<html>', '<head>', '<meta charset="utf-8">',
    '<title>Notes usage report</title>', '</head>', '<body>', '<pre>',
    ...buildReport(notes, options).split('\n').map(escapeHtml),
    '</pre>', '</body>', '</html>',
  ].join('\n');

const summarize = (notes) => ({
  total: notes.length,
  tags: Object.keys(countByTag(notes)).length,
  averageLength: Math.round(averageLength(notes)),
  busiestDay: topEntries(countByWeekday(notes), 1)[0]?.key ?? null,
});

function compareSummaries(before, after) {
  const diff = {};
  for (const k of ['total', 'tags', 'averageLength']) diff[k] = (after[k] || 0) - (before[k] || 0);
  diff.busiestDayChanged = before.busiestDay !== after.busiestDay;
  return diff;
}

function describeChange(diff) {
  const parts = [];
  if (diff.total) parts.push(`${sign(diff.total)}${formatNumber(diff.total)} notes`);
  if (diff.tags) parts.push(`${sign(diff.tags)}${diff.tags} tags`);
  if (diff.averageLength) {
    parts.push(`average length ${diff.averageLength > 0 ? 'up' : 'down'} ${Math.abs(diff.averageLength)} chars`);
  }
  if (diff.busiestDayChanged) parts.push('busiest day changed');
  return parts.length ? parts.join(', ') : 'no change';
}

export {
  buildHtml, buildWeekdaySection, summarize, compareSummaries, describeChange,
  buildReport, buildCsv, formatDate, formatNumber, percent, countByTag, topEntries,
};

