function validateOptions({ sections, format, now } = {}) {
  if (sections && !Array.isArray(sections)) throw new Error('sections must be an array');
  if (format && format !== 'text' && format !== 'csv') throw new Error(`unknown format: ${format}`);
  return {
    sections: sections || ['daily', 'weekly', 'monthly'],
    format: format || 'text',
    now: now || Date.now(),
  };
}

function buildReport(notes, options) {
  const opts = validateOptions(options);
  if (opts.format === 'csv') return buildCsv(notes);
  return [
    buildHeader('Notes usage report', opts.now),
    ...opts.sections.map((s) =>
      Object.hasOwn(SECTIONS, s) ? buildSection(s, notes, opts.now) : `(unknown section: ${s})`),
    buildFooter(notes),
  ].join('\n\n');
}

